58	  --bg: #0b0e14;
59	  --bg-elevated: #12161f;
60	  --bg-sunken: #0d1017;
61	  --border: #21262f;
62	  --border-strong: #2d333d;
63	  --text: #e6e8eb;
64	  --text-secondary: #9aa4b2;
65	  --text-muted: #616b7a;
66	  --accent: #818cf8;
67	  --accent-soft: #1e1b3a;
68	  --ok: #34d399;
69	  --ok-soft: #06281f;
70	  --warn: #fbbf24;
71	  --warn-soft: #2b1f06;
72	  --bad: #f87171;
73	  --bad-soft: #2a1414;
74	  --info: #38bdf8;
75	  --info-soft: #07222e;
76	  --shadow: 0 1px 2px rgba(0, 0, 0, 0.3), 0 1px 3px rgba(0, 0, 0, 0.4);
77	  --shadow-lg: 0 16px 40px -12px rgba(0, 0, 0, 0.6);
