79	
80	* { box-sizing: border-box; margin: 0; padding: 0; }
81	
82	html { font-size: 15px; }
83	
84	body {
85	  font-family: var(--sans);
86	  background: var(--bg);
87	  color: var(--text);
88	  line-height: 1.5;
89	  -webkit-font-smoothing: antialiased;
90	}
91	
92	a { color: inherit; text-decoration: none; }
93	button { font: inherit; cursor: pointer; border: none; background: none; color: inherit; }
94	code, pre, .mono { font-family: var(--mono); font-size: 0.86em; }
95	
96	table.mini { width: 100%; border-collapse: collapse; font-size: 13px; }
97	table.mini th { text-align: left; padding: 5px 8px; color: var(--text-muted); font-weight: 500; border-bottom: 1px solid var(--border); }
98	table.mini td { padding: 5px 8px; border-bottom: 1px solid var(--border); vertical-align: top; }
99	table.mini tr:last-child td { border-bottom: none; }
100	
101	/* --- layout --- */
102	
103	.app { display: grid; grid-template-columns: 232px 1fr; min-height: 100vh; }
104	
105	.sidebar {
106	  border-right: 1px solid var(--border);
107	  background: var(--bg-elevated);
108	  padding: 20px 14px;
109	  display: flex;
110	  flex-direction: column;
111	  gap: 4px;
112	  position: sticky;
113	  top: 0;
114	  height: 100vh;
115	  overflow-y: auto;
116	}
117	
118	.brand {
119	  display: flex;
120	  align-items: center;
121	  gap: 10px;
122	  padding: 4px 8px 18px;
123	}
124	.brand .logo {
125	  width: 30px; height: 30px;
126	  border-radius: 8px;
127	  background: linear-gradient(135deg, var(--accent), var(--info));
128	  display: grid; place-items: center;
129	  color: #fff; font-weight: 800; font-size: 14px;
130	  letter-spacing: -0.5px;
131	}
132	.brand .name { font-weight: 700; letter-spacing: -0.2px; }
133	.brand .sub { font-size: 11px; color: var(--text-muted); }
134	
135	.nav-link {
136	  display: flex; align-items: center; gap: 10px;
137	  padding: 8px 10px;
138	  border-radius: var(--radius-sm);
139	  color: var(--text-secondary);
140	  font-size: 14px;
141	  font-weight: 500;
142	  transition: background 0.12s, color 0.12s;
143	}
144	.nav-link:hover { background: var(--bg-sunken); color: var(--text); }
145	.nav-link.active { background: var(--accent-soft); color: var(--accent); }
146	.nav-link .ico { width: 16px; height: 16px; opacity: 0.9; flex: none; }
147	
148	.sidebar .spacer { flex: 1; }
149	.sidebar-foot { font-size: 11px; color: var(--text-muted); padding: 8px; }
150	.theme-toggle {
151	  display: flex; align-items: center; gap: 8px;
152	  padding: 8px 10px; border-radius: var(--radius-sm);
153	  color: var(--text-secondary); font-size: 13px;
154	}
155	.theme-toggle:hover { background: var(--bg-sunken); }
156	
157	.main { padding: 28px 34px 60px; max-width: 1180px; width: 100%; }
158	
159	.page-head { margin-bottom: 22px; }
160	.page-head h1 { font-size: 22px; font-weight: 700; letter-spacing: -0.4px; }
161	.page-head p { color: var(--text-secondary); font-size: 14px; margin-top: 3px; }
162	
163	/* --- primitives --- */
164	
165	.card {
166	  background: var(--bg-elevated);
167	  border: 1px solid var(--border);
168	  border-radius: var(--radius);
169	  box-shadow: var(--shadow);
170	}
171	.card-pad { padding: 18px 20px; }
172	.card-head {
173	  padding: 14px 20px;
174	  border-bottom: 1px solid var(--border);
175	  font-weight: 600;
176	  font-size: 13px;
177	  letter-spacing: 0.02em;
178	  text-transform: uppercase;
179	  color: var(--text-secondary);
180	}
181	
182	.grid { display: grid; gap: 16px; }
183	.grid.cols-2 { grid-template-columns: 1fr 1fr; }
184	.grid.cols-3 { grid-template-columns: repeat(3, 1fr); }
185	.grid.cols-4 { grid-template-columns: repeat(4, 1fr); }
186	@media (max-width: 900px) {
187	  .app { grid-template-columns: 1fr; }
188	  .sidebar { position: static; height: auto; flex-direction: row; flex-wrap: wrap; }
189	  .grid.cols-2, .grid.cols-3, .grid.cols-4 { grid-template-columns: 1fr; }
190	}
191	
192	.stat { padding: 16px 18px; }
193	.stat .label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; }
194	.stat .value { font-size: 26px; font-weight: 700; letter-spacing: -0.5px; margin-top: 4px; }
195	.stat .value.mono { font-size: 20px; }
196	.stat .foot { font-size: 12px; color: var(--text-secondary); margin-top: 3px; }
197	
198	.badge {
199	  display: inline-flex; align-items: center; gap: 5px;
200	  padding: 2px 8px; border-radius: 999px;
201	  font-size: 11.5px; font-weight: 600; letter-spacing: 0.02em;
202	  border: 1px solid transparent;
203	}
204	.badge .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
205	.badge.SUCCESS, .badge.pass, .badge.up, .badge.COMPLETE { color: var(--ok); background: var(--ok-soft); }
206	.badge.REGRESSION, .badge.ERROR, .badge.fail, .badge.down, .badge.FAILED { color: var(--bad); background: var(--bad-soft); }
207	.badge.PARTIAL_SUCCESS, .badge.NEEDS_REVIEW, .badge.uncertain, .badge.PARTIAL { color: var(--warn); background: var(--warn-soft); }
208	.badge.IN_PROGRESS, .badge.linked, .badge.NOT_STARTED { color: var(--info); background: var(--info-soft); }
209	.badge.missing { color: var(--text-muted); background: var(--bg-sunken); }
210	
211	.pill { font-family: var(--mono); font-size: 11.5px; background: var(--bg-sunken); border: 1px solid var(--border); padding: 1px 6px; border-radius: 5px; color: var(--text-secondary); }
212	
213	.muted { color: var(--text-muted); }
214	.secondary { color: var(--text-secondary); }
215	.plus { color: var(--ok); }
216	.minus { color: var(--bad); }
217	
218	/* --- version list / timeline --- */
219	
220	.vrow {
221	  display: grid;
222	  grid-template-columns: 44px 110px 1fr auto;
223	  gap: 14px;
224	  align-items: center;
225	  padding: 12px 20px;
226	  border-bottom: 1px solid var(--border);
227	  transition: background 0.1s;
228	}
229	.vrow:last-child { border-bottom: none; }
230	.vrow:hover { background: var(--bg-sunken); }
231	.vrow .vid { font-weight: 700; font-size: 14px; }
232	.vrow .vintent { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 14px; }
233	.vrow .vmeta { font-size: 12px; color: var(--text-muted); display: flex; gap: 10px; }
234	
235	.timeline { position: relative; padding-left: 30px; }
236	.timeline::before { content: ""; position: absolute; left: 9px; top: 8px; bottom: 8px; width: 2px; background: var(--border); }
237	.tl-item { position: relative; padding: 14px 0; border-bottom: 1px solid var(--border); }
238	.tl-item:last-child { border-bottom: none; }
239	.tl-item::before {
240	  content: ""; position: absolute; left: -25px; top: 20px;
241	  width: 12px; height: 12px; border-radius: 50%;
242	  background: var(--bg); border: 2.5px solid var(--border-strong);
243	}
244	.tl-item.SUCCESS::before { border-color: var(--ok); }
245	.tl-item.REGRESSION::before, .tl-item.ERROR::before { border-color: var(--bad); }
246	.tl-item.PARTIAL_SUCCESS::before, .tl-item.NEEDS_REVIEW::before { border-color: var(--warn); }
247	.tl-head { display: flex; align-items: center; gap: 10px; }
248	.tl-head .vid { font-weight: 700; }
249	.tl-body { margin-top: 4px; font-size: 14px; }
250	.tl-metrics { margin-top: 6px; display: flex; gap: 8px; flex-wrap: wrap; }
251	
252	/* --- development trace --- */
253	
254	.trace { display: flex; flex-direction: column; gap: 0; }
255	.trace-node {
256	  position: relative;
257	  display: grid;
258	  grid-template-columns: 130px 1fr;
259	  gap: 16px;
260	  padding: 12px 0 12px 22px;
261	}
262	.trace-node::before {
263	  content: ""; position: absolute; left: 5px; top: 18px;
264	  width: 10px; height: 10px; border-radius: 50%;
265	  background: var(--accent); box-shadow: 0 0 0 4px var(--accent-soft);
266	}
267	.trace-node:not(:last-child)::after {
268	  content: ""; position: absolute; left: 9px; top: 28px; bottom: -12px; width: 2px;
269	  background: var(--border-strong);
270	}
271	.trace-node .t-label { font-size: 12px; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.04em; padding-top: 2px; }
272	.trace-node .t-value { font-size: 14px; font-weight: 500; word-break: break-word; }
273	.trace-node .t-detail { font-size: 12.5px; color: var(--text-secondary); margin-top: 2px; }
274	.trace-node[data-source="entire"]::before { background: var(--info); box-shadow: 0 0 0 4px var(--info-soft); }
275	.trace-node[data-source="status"]::before { background: var(--warn); box-shadow: 0 0 0 4px var(--warn-soft); }
276	
277	/* --- diff viewer --- */
278	
279	.diff {
280	  font-family: var(--mono);
281	  font-size: 12.5px;
282	  line-height: 1.55;
283	  background: var(--bg-sunken);
284	  border: 1px solid var(--border);
285	  border-radius: var(--radius-sm);
286	  overflow-x: auto;
287	  max-height: 560px;
288	  overflow-y: auto;
289	}
290	.diff .l { display: block; padding: 0 12px; white-space: pre; }
291	.diff .l.add { background: var(--ok-soft); color: var(--ok); }
292	.diff .l.del { background: var(--bad-soft); color: var(--bad); }
293	.diff .l.hunk { color: var(--info); background: var(--info-soft); }
294	.diff .l.meta { color: var(--text-muted); }
295	
296	/* --- misc --- */
297	
298	.kv { display: grid; grid-template-columns: 130px 1fr; gap: 6px 16px; font-size: 14px; }
299	.kv dt { color: var(--text-muted); }
300	.kv dd { word-break: break-word; }
301	
302	.files-list { font-family: var(--mono); font-size: 12.5px; }
303	.files-list .f { display: flex; gap: 10px; padding: 4px 0; align-items: baseline; }
304	.files-list .mark { width: 14px; font-weight: 700; }
305	.files-list .mark.A { color: var(--ok); }
306	.files-list .mark.M { color: var(--warn); }
307	.files-list .mark.D { color: var(--bad); }
308	.files-list .mark.R, .files-list .mark.C { color: var(--info); }
309	
310	.search-box {
311	  width: 100%;
312	  padding: 11px 14px;
313	  border-radius: var(--radius);
314	  border: 1px solid var(--border-strong);
315	  background: var(--bg-elevated);
316	  color: var(--text);
317	  font-size: 15px;
318	}
319	.search-box:focus { outline: 2px solid var(--accent); outline-offset: -1px; border-color: transparent; }
320	
321	select.search-box { cursor: pointer; }
322	
323	.empty { text-align: center; padding: 48px 20px; color: var(--text-muted); }
324	.empty .big { font-size: 15px; color: var(--text-secondary); margin-bottom: 4px; }
325	
326	.toast {
327	  position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
328	  background: var(--bad); color: #fff; padding: 10px 18px; border-radius: 8px;
329	  font-size: 13px; box-shadow: var(--shadow-lg); z-index: 50;
330	}
331	
332	.link { color: var(--accent); font-weight: 500; }
333	.link:hover { text-decoration: underline; }
334	
335	.metric-delta { display: inline-flex; align-items: baseline; gap: 6px; font-family: var(--mono); font-size: 13px; }
336	.metric-delta .arrow { color: var(--text-muted); }
337	
338	.spin { display: inline-block; width: 16px; height: 16px; border: 2px solid var(--border-strong); border-top-color: var(--accent); border-radius: 50%; animation: spin 0.7s linear infinite; }
339	@keyframes spin { to { transform: rotate(360deg); } }
340	
341	hr.sep { border: none; border-top: 1px solid var(--border); margin: 22px 0; }
342

