  --bg-active: #e9eaef;

  --border: #e6e7ec;
  --border-strong: #d7d9e0;
  --border-accent: #d7d4fa;

  --text: #15171d;
  --text-secondary: #565c6b;
  --text-muted: #878d9b;
  --text-on-accent: #ffffff;

  /* -- brand + semantic ------------------------------------------------- */
  --accent: #5b53e8;
  --accent-hover: #4a41dd;
  --accent-press: #3f37c9;
  --accent-soft: #eeedfd;
  --accent-border: #d9d6fa;
  --accent-text: #4b41d1;

  --ok: #12805c;
  --ok-soft: #e4f5ee;
  --ok-border: #b9e2d1;
  --ok-strong: #0e6b4d;

  --warn: #9a6700;
  --warn-soft: #fbf1de;
  --warn-border: #ecd9a8;
  --warn-strong: #855800;

  --bad: #cf2230;
  --bad-soft: #fdeceb;
  --bad-border: #f3c4c1;
  --bad-strong: #b31b28;

  --info: #0e6fd6;
  --info-soft: #e7f1fd;
  --info-border: #bcdafb;
  --info-strong: #0a5bb0;

  /* -- data-viz series (color-blind-tuned; see charts) ----------------- */
  --series-1: #5b53e8;
  --series-2: #0e9f9f;
  --series-3: #e0821d;
  --series-4: #c6417c;
  --series-5: #6b8f2e;
  --series-6: #8a63d2;

  /* -- radius / elevation / motion ------------------------------------- */
  --r-1: 6px;
  --r-2: 9px;
  --r-3: 13px;
  --r-full: 999px;

  --shadow-xs: 0 1px 2px rgba(15, 17, 28, 0.04);
  --shadow-sm: 0 1px 3px rgba(15, 17, 28, 0.06), 0 1px 2px rgba(15, 17, 28, 0.04);
