interface Point {
  value: number | null;
  label?: string;
  adverse?: boolean;
}

/** Minimal inline sparkline. Nulls break the line. */
export function Sparkline({
  points,
  width = 240,
  height = 44,
  strokeVar = "--accent",
}: {
  points: Point[];
  width?: number;
  height?: number;
  strokeVar?: string;
}) {
  const vals = points.map((p) => p.value).filter((v): v is number => v != null);
  if (vals.length < 2) return <span className="muted text-xs">not enough data</span>;

  const min = Math.min(...vals);
  const max = Math.max(...vals);
  const range = max - min || 1;
  const pad = 4;
  const n = points.length;

  const coords = points.map((p, i) => {
    const x = n === 1 ? width / 2 : (i / (n - 1)) * (width - pad * 2) + pad;
    const y =
      p.value == null ? null : height - pad - ((p.value - min) / range) * (height - pad * 2);
    return { x, y, p };
  });

  let d = "";
  coords.forEach((c) => {
    if (c.y == null) {
      d += " ";
      return;
    }
    d += `${d.trimEnd().endsWith("M") || d === "" || d.trimEnd().slice(-1) === " " ? "M" : "L"}${c.x.toFixed(1)},${c.y.toFixed(1)} `;
  });

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} preserveAspectRatio="none">
      <path d={d.trim()} fill="none" stroke={`var(${strokeVar})`} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
      {coords.map((c, i) =>
        c.y == null ? null : (
          <circle
            key={i}
            cx={c.x}
            cy={c.y}
            r={c.p.adverse ? 3.5 : 2.5}
            fill={c.p.adverse ? "var(--bad)" : `var(${strokeVar})`}
          >
            {c.p.label && <title>{c.p.label}</title>}
          </circle>
        ),
      )}
    </svg>
  );
}

