                  <a
                    key={s}
                    href={`#${s}`}
                    className={`subnav__link${activeSection === s ? " subnav__link--active" : ""}`}
                  >
                    {label}
                  </a>
                ),
              )}
            </nav>

            <section id="trace" className="stack scroll-mt">
              <div className="grid grid--2" style={{ alignItems: "start" }}>
