                            <div key={m.name} className="metric-row">
                              <span>{m.name}</span>
                              <span className="mono tnum">
                                {m.before != null && (
                                  <span className="muted">{m.before} → </span>
                                )}
                                <span className={trend === "up" ? "plus" : trend === "down" ? "minus" : ""}>
