                    </span>
                  }
                  pad
                >
                  <p style={{ fontSize: "0.9375rem" }}>{v.analysis.summary}</p>
                  {v.analysis.reasoning && (
                    <p className="secondary text-sm" style={{ marginTop: 8 }}>
                      {v.analysis.reasoning}
                    </p>
                  )}
                  {v.analysis.recommendation && (
                    <p style={{ marginTop: 10 }}>
