function ImpactTable({ entities }: { entities: DevelopmentVersion["changed_files"] extends never ? never : import("@/api/types").ChangedEntity[] }) {
  const rows = entities.slice().sort((a, b) => b.dependents_count - a.dependents_count).slice(0, 40);
