              {t}
            </text>
          </g>
        ))}
        {xTicks.map((t) => (
          <text key={"x" + t} x={px(t)} y={height - 8} textAnchor="middle" fontSize={11} fill="var(--text-muted)">
            {t}
          </text>
        ))}
        <text x={PLOT.left + iw / 2} y={height} textAnchor="middle" fontSize={10} fill="var(--text-muted)">
          total changes
        </text>
        {data.map((d, i) => (
          <circle
            key={i}
            cx={px(d.x)}
            cy={py(d.y)}
            r={6}
            fill={d.y > 0 ? "var(--bad)" : "var(--series-1)"}
            fillOpacity={0.8}
            stroke="var(--bg-elevated)"
            strokeWidth={1.5}
            onMouseEnter={() => setHover({ x: px(d.x), y: py(d.y), datum: d })}
            onMouseLeave={() => setHover(null)}
          />
        ))}
      </svg>
      {hover && (
        <Tooltip x={hover.x} y={hover.y}>
          <b className="mono">{hover.datum.label}</b>
          <div>
            {hover.datum.x} changes · {hover.datum.y} adverse
          </div>
        </Tooltip>
      )}
    </div>
  );
}

/* -- resize helper ------------------------------------------------- */

function useResize(ref: React.RefObject<HTMLElement>, cb: (w: number) => void) {
  const raf = useRef(0);
  const set = (w: number) => {
    cancelAnimationFrame(raf.current);
    raf.current = requestAnimationFrame(() => cb(Math.max(240, w)));
  };
  // measure on mount + observe
  if (typeof window !== "undefined") {
    queueMicrotask(() => {
      if (ref.current) set(ref.current.clientWidth);
    });
  }
  useObserver(ref, set);
}

function useObserver(ref: React.RefObject<HTMLElement>, set: (w: number) => void) {
  const obs = useRef<ResizeObserver | null>(null);
  if (typeof ResizeObserver !== "undefined" && ref.current && !obs.current) {
    obs.current = new ResizeObserver((entries) => {
      for (const e of entries) set(e.contentRect.width);
    });
    obs.current.observe(ref.current);
  }
}

