              {t}
            </text>
          </g>
        ))}
        {data.map((d, i) => (
          <text key={i} x={px(i)} y={height - 8} textAnchor="middle" fontSize={11} fill="var(--text-muted)">
            {d.label}
          </text>
        ))}
        <g clipPath={`url(#${clipId})`}>
          {segs.map((s, i) => (
            <path key={i} d={s} fill="none" stroke="var(--series-1)" strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
          ))}
        </g>
        {data.map((d, i) =>
