              y={PLOT.top}
              width={iw / data.length}
              height={ih}
              fill="transparent"
              onMouseEnter={() => setHover({ x: px(i), y: py(d.value!), datum: d })}
              onMouseLeave={() => setHover(null)}
            />
          ),
