/* -- resize helper ------------------------------------------------- */

function useResize(ref: React.RefObject<HTMLElement>, cb: (w: number) => void) {
  const raf = useRef(0);
  const set = (w: number) => {
    cancelAnimationFrame(raf.current);
    raf.current = requestAnimationFrame(() => cb(Math.max(240, w)));
  };
  // measure on mount + observe
  if (typeof window !== "undefined") {
    queueMicrotask(() => {
      if (ref.current) set(ref.current.clientWidth);
    });
  }
  useObserver(ref, set);
}

function useObserver(ref: React.RefObject<HTMLElement>, set: (w: number) => void) {
  const obs = useRef<ResizeObserver | null>(null);
  if (typeof ResizeObserver !== "undefined" && ref.current && !obs.current) {
    obs.current = new ResizeObserver((entries) => {
      for (const e of entries) set(e.contentRect.width);
    });
    obs.current.observe(ref.current);
  }
}

